```sql
/* Находим молекулы, содержащие атомы натрия (element = 'na') */
WITH sodium_molecules AS (
    SELECT DISTINCT a."molecule_id"
    FROM "atom" a
    WHERE a."element" = 'na'
)
/* Считаем среди них молекулы с меткой '-' (non-carcinogenic) */
SELECT COUNT(DISTINCT m."molecule_id") AS non_carcinogenic_count
FROM "molecule" m
JOIN sodium_molecules sm ON sm."molecule_id" = m."molecule_id"
WHERE m."label" = '-';
```

```sql
/* Подсчёт общего числа атомов в молекулах, содержащих тройные связи и атомы фосфора или брома */
SELECT COUNT(DISTINCT a."atom_id") AS total_atoms
FROM "atom" a
JOIN "molecule" m ON m."molecule_id" = a."molecule_id"
WHERE a."molecule_id" IN (
    /* Молекулы с тройными связями */
    SELECT b."molecule_id"
    FROM "bond" b
    WHERE b."bond_type" = '#'
)
AND a."molecule_id" IN (
    /* Молекулы, содержащие фосфор или бром */
    SELECT a2."molecule_id"
    FROM "atom" a2
    WHERE a2."element" IN ('p', 'br')
);
```

```sql
/* Доля карт с французским языком среди карт Story Spotlight */
SELECT
    /* Процент: французские Story Spotlight / все Story Spotlight * 100 */
    ROUND(
        COUNT(DISTINCT CASE WHEN fd."language" = 'French' THEN c."id" END)::numeric
        / NULLIF(COUNT(DISTINCT c."id"), 0) * 100,
        2
    ) AS "percentage_french_story_spotlight"
FROM "cards" c
/* Соединяем с foreign_data по uuid для получения языка */
JOIN "foreign_data" fd
    ON fd."uuid" = c."uuid"
WHERE c."isstoryspotlight" = '1';
```

```sql
/* Находим пользователя(ей) с минимальной репутацией */
WITH min_rep AS (
    SELECT MIN(CAST("reputation" AS BIGINT)) AS min_reputation
    FROM "users"
),
/* Определяем id пользователей с минимальной репутацией */
lowest_users AS (
    SELECT u."id"
    FROM "users" u
    JOIN min_rep m ON CAST(u."reputation" AS BIGINT) = m.min_reputation
)
/* Выводим уникальные названия бейджей, полученных этими пользователями */
SELECT DISTINCT b."name"
FROM "badges" b
JOIN lowest_users lu ON b."userid" = lu."id"
ORDER BY b."name";
```

