```sql
/* Доля супергероев-женщин среди "плохих" супергероев (alignment.id = 2), в процентах */
SELECT
    /* Процент = (кол-во женщин среди bad) / (общее кол-во bad) * 100 */
    (SUM(CASE WHEN s."gender_id" = 2 THEN 1 ELSE 0 END)::numeric
     / COUNT(*)::numeric) * 100.0 AS female_percentage
FROM "superhero" s
JOIN "alignment" a ON a."id" = s."alignment_id"
WHERE a."id" = 2;
```

```sql
/* Процент героев Marvel Comics среди супергероев с ростом от 150 до 180 см */
SELECT
    /* Расчёт процента: доля героев Marvel Comics, умноженная на 100 */
    (SUM(CASE WHEN p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END)::numeric
     / COUNT(p."id")::numeric) * 100 AS marvel_percentage
FROM "superhero" s
JOIN "publisher" p ON s."publisher_id" = p."id"
WHERE s."height_cm"::numeric BETWEEN 150 AND 180;
```

```sql
/* Доля супергероев с alignment = 'Bad' от общего числа супергероев (в процентах) */
SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE al."alignment" = 'Bad') / NULLIF(COUNT(sh."id"), 0),
        2
    ) AS bad_percentage,
    /* Количество супергероев с alignment = 'Bad', опубликованных Marvel Comics */
    COUNT(*) FILTER (
        WHERE al."alignment" = 'Bad'
          AND p."publisher_name" = 'Marvel Comics'
    ) AS bad_marvel_count
FROM "superhero" sh
LEFT JOIN "alignment" al ON al."id" = sh."alignment_id"
LEFT JOIN "publisher" p ON p."id" = sh."publisher_id";
```

```sql
/* Superheroes with missing weight data (weight_kg = 0 or NULL) */
/* Count those with blue eyes (colour.id = 7) vs no eye colour (colour.id = 1) */
/* Return the difference: blue_eyes_count - no_eye_colour_count */
SELECT
    SUM(CASE WHEN c.id = 7 THEN 1 ELSE 0 END)
    - SUM(CASE WHEN c.id = 1 THEN 1 ELSE 0 END) AS difference
FROM superhero s
LEFT JOIN colour c ON s.eye_colour_id = c.id
WHERE s.weight_kg = 0 OR s.weight_kg IS NULL;
```

